/* Warehouse episode: checks never repair the order. */
(() => {
  'use strict';
  window.OchakovoShift.register('warehouse', a => {
    const {products,getProduct,totalNeed,unitNeed,create}=window.WarehouseTraining;
    const game=create(),s=game.state,b=a.button,e=a.esc;
    const phases=['Задание','Комплектация','Сверка','Передача'];
    let phase=0,view='racks',address='A-01-01',addressScanned=false,selected='',detail='label',problemOpen=false,reason='',message='',mood='think',hint=0,inlineMessage='';
    const icons={box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4ZM3 7l9 4 9-4M12 11v11m-4-17 9 4"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M4 12h16M8 8v8m4-8v8m4-8v8"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',warning:'<path d="m12 3 10 18H2ZM12 9v5m0 3v1"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3M8 17l4 3 4-3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'};
    const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${icons[name]||icons.box}</svg>`;
    const button=(action,label,value='',cls='wh-button',attrs='')=>b(action,label,value,cls,attrs);
    const noun=(n,one,few,many)=>n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;
    const unitText=n=>n+' '+noun(n,'единица','единицы','единиц');
    const boxText=n=>n+' '+noun(n,'коробка','коробки','коробок');
    const units=()=>game.selected().reduce((n,c)=>n+getProduct(c.sku).units,0);
    const status=()=>s.transferred?'Передан в зону отгрузки':game.ready()?'Проверен · готов к передаче':s.checkedRevision>=0&&s.checkedRevision!==s.revision?'Изменён · нужна сверка':s.checkedRevision===s.revision&&s.issues.length?'Требует исправления':s.started?'Комплектуется':'Получен';
    function notify(text,ok=false,local=false){message=text;inlineMessage=local?text:'';mood=ok?'success':'think';a.say(text,mood);}
    function packageIcon(kind){return kind==='can'?'<svg viewBox="0 0 28 46" fill="none" aria-hidden="true"><rect x="4" y="4" width="20" height="38" rx="5" stroke="currentColor" stroke-width="1.5"/><path d="M6 9h16M6 37h16m-11-31h6" stroke="currentColor" stroke-width="1.5"/></svg>':'<svg viewBox="0 0 28 46" fill="none" aria-hidden="true"><path d="M10 3h8v7l4 7v25H6V17l4-7Z" stroke="currentColor" stroke-width="1.5"/><path d="M10 7h8M6 22h16M6 34h16" stroke="currentColor" stroke-width="1.5"/></svg>';}
    function carton(c,large=false){const p=getProduct(c.sku);return `<span class="wh-carton wh-carton--${p.tone} ${large?'wh-carton--large':''} ${c.damaged?'wh-carton--torn':''}" aria-hidden="true"><span class="wh-carton-top"><span>${c.id}</span><span>↑ ↑</span></span><span class="wh-carton-face"><strong>${p.brand}</strong><span class="wh-carton-format">${packageIcon(p.kind)}<span>${p.format}<b>${p.units} ${p.kind==='can'?'банки':'бутылок'}</b></span></span><span class="wh-carton-bottom"><span>${p.sku}</span><i class="wh-barcode"></i></span></span>${c.damaged?'<svg class="wh-tear" viewBox="0 0 60 50"><path d="m0 15 17 7 9-14 6 22 14-8 14 15-18-3-12 16-9-17-14 3Z" fill="#635342"/><path d="m1 14 17 5 9-15 8 21 11-7 14 17" stroke="#ead4ae" stroke-width="4"/></svg>':''}</span>`;}
    function order(compact=false){return `<section class="wh-order ${compact?'is-compact':''}" aria-label="Задание на комплектацию F-78"><header><div>${icon('box')}<strong>Заказ F-78</strong><span>Магазин «Север»</span></div><span>${totalNeed} коробок · ${unitText(unitNeed)}</span></header><div class="wh-order-head"><span>Товар · учебный формат</span><span>Нужно / собрано</span></div>${products.filter(p=>p.need).map(p=>`<div class="wh-order-row ${s.checkedRevision===s.revision&&s.issues.some(i=>i.kind==='count'&&i.sku===p.sku)?'has-error':''}"><div><strong>${p.brand}</strong><span>${p.format} × ${p.units}</span><small>${p.sku} · ${p.address}</small></div><div class="wh-order-count"><strong>${p.need}<span> / ${game.rows().find(r=>r.sku===p.sku).actual}</span></strong><small class="wh-count-label">Нужно / собрано</small></div></div>`).join('')}<footer>Собираем целыми коробками. Форматы упаковки учебные.</footer></section>`;}
    function guide(){return `<div class="wh-guide ${mood==='success'?'is-success':''}" role="status" aria-live="polite" aria-atomic="true"><span class="wh-guide-avatar">${icon('person')}</span><div><strong>Наставник склада</strong><p>${e(message||'Сверяй товар, формат и количество. Если заметишь проблему, разберём её вместе.')}</p></div></div>`;}
    function intro(){return `<div class="wh-intro"><div class="wh-intro-copy"><h2>Шесть коробок.<br>Один точный заказ.</h2><p>Ты стажёр склада. Найди нужные позиции, собери заказ и проверь его перед передачей следующей команде.</p><div class="wh-flow"><span>Производство</span>${icon('arrow')}<strong>Склад</strong>${icon('arrow')}<span>Логистика</span></div><p class="wh-intro-note">Кладовщик передал задание F-78. На стеллажах есть похожие товары — обращай внимание на этикетки.</p>${button('wh-start','Принять задание '+icon('arrow'),'','primary')}<span class="wh-duration">7–10 минут · в твоём темпе</span></div><div class="wh-intro-art"><div class="wh-building-sign">ОЧАКОВО <span>Учебный склад</span></div><div class="wh-mini-rack">${s.boxes.filter(c=>['CB-01','CC-01','FA-01'].includes(c.id)).map(c=>`<div>${carton(c)}<span>${c.address}</span></div>`).join('')}</div><div class="wh-floor-mark">Зона комплектации · F-78</div></div></div>${order()}<details class="wh-help"><summary>Как прочитать задание?</summary><p>«Нужно 2» — две целые коробки. «× 12» — двенадцать единиц внутри каждой. Два формата CoolCola — две отдельные позиции.</p></details>`;}
    function tabs(){return `<nav class="wh-tabs" aria-label="Рабочая область">${[['racks','Стеллажи'],['assembly',`Комплектация · ${game.selected().length}`],['check','Сверка']].map(([id,text])=>button('wh-tab',text,id,'wh-tab '+(view===id?'is-active':''),`aria-pressed="${view===id}"`)).join('')}</nav>`;}
    function racks(){const addresses=[...new Set(products.map(p=>p.address)),'R-01-01'];const list=s.boxes.filter(c=>c.address===address&&game.available(c));return `<section class="wh-rack-scene" aria-label="Адресные стеллажи"><div class="wh-rack-caption"><h2>Найди нужную ячейку</h2><details class="wh-address-help"><summary>${icon('info')} Адрес</summary><p>A — ряд, 01 — секция, 01 — ячейка. В этой учебной сцене всё доступно с пола.</p></details></div><div class="wh-addresses" aria-label="Адреса хранения">${addresses.map(ad=>button('wh-address',ad,ad,'wh-address '+(address===ad?'is-active':''),`aria-pressed="${address===ad}" ${ad[0]==='R'&&!s.released?'disabled title="Резерв доступен по решению кладовщика"':''}`)).join('')}</div>${!s.released?'<p class="wh-reserve-note">R-01-01 · резерв по решению кладовщика</p>':''}<div class="wh-rack-header"><strong>${address}</strong><span>${addressScanned?icon('check')+' Адрес считан':'Адрес ещё не сканирован'}</span>${button('wh-scan-address',icon('scan')+' Сканировать адрес')}</div><div class="wh-shelf ${addressScanned?'is-scanned':''}">${list.length?list.map(c=>button('wh-select',`${carton(c)}<span class="wh-box-id">${c.id}${c.scanned?' · код считан':''}${c.inspection==='good'?' · осмотрена':''}</span>`,c.id,'wh-rack-box '+(selected===c.id?'is-selected':''),`aria-label="Выбрать ${getProduct(c.sku).brand}, ${getProduct(c.sku).format}, ${c.id}" aria-pressed="${selected===c.id}" data-drag="${c.id}" draggable="true"`)).join(''):'<p class="wh-empty">В этой ячейке доступных коробок не осталось. Проверь другие адреса или собранный состав.</p>'}</div><div class="wh-shelf-beam"><span>${address}</span><i></i><i></i></div><p class="wh-scene-tip">${icon('eye')} Адрес показывает место. Этикетка — товар внутри.</p></section>`;}
    function assembly(){const boxes=game.selected();return `<section class="wh-assembly" data-drop="assembly" aria-label="Зона комплектации"><div class="wh-section-heading"><h2>Зона комплектации</h2><span>${boxText(boxes.length)} · ${unitText(units())}</span></div>${boxes.length?`<div class="wh-assembly-grid">${boxes.map(c=>`<article class="wh-assembly-box ${selected===c.id?'is-selected':''}">${button('wh-select',carton(c),c.id,'wh-box-select',`aria-label="Открыть ${c.id}, ${getProduct(c.sku).brand}, ${getProduct(c.sku).format}"`)}<div class="wh-box-caption"><strong>${c.id}</strong><span>${c.inspection==='damage'?'Есть повреждение':!c.inspection?'Не осмотрена':!c.scanned?'Не сканирована':'Код и осмотр отмечены'}</span></div>${button(c.inspection==='damage'?'wh-problem':'wh-return',c.inspection==='damage'?'Разобраться с повреждением':'Вернуть на '+c.address,c.id,'wh-return',`aria-label="${c.inspection==='damage'?'Разобраться с повреждением':'Вернуть коробку'} ${c.id}${c.inspection==='damage'?'':' на '+c.address}"`)}</article>`).join('')}</div>`:`<div class="wh-empty-zone">${icon('box')}<h3>Заказ пока пуст</h3><p>Выбери коробку на стеллаже и добавь её сюда. Можно нажать кнопку или перетащить коробку.</p>${button('wh-tab','Открыть стеллажи','racks')}</div>`}<div class="wh-assembly-floor"><span>F-78</span><span>Учебный магазин «Север»</span></div></section>`;}
    function checkView(){const stale=s.checkedRevision!==s.revision,issues=stale?[]:s.issues;return `<section class="wh-check"><div class="wh-section-heading"><h2 tabindex="-1" id="wh-check-title">Сверка заказа</h2><span>${game.selected().length} / ${totalNeed} коробок</span></div><p class="wh-check-intro">${s.checkedRevision<0?'Сравни фактический состав с документом F-78. Проверка сохранит все выбранные коробки.':stale?'Заказ изменён после проверки. Выполни сверку ещё раз.':issues.length?'Есть расхождения. Выбери строку, чтобы разобраться и исправить состав.':'Состав и упаковка проверены. Заказ готов к передаче.'}</p><div class="wh-compare-head"><span>Позиция</span><span>Нужно / факт</span></div>${game.rows().filter(p=>p.need||p.actual).map(p=>{const diff=p.actual-p.need,wrong=!stale&&diff!==0;return `<div class="wh-compare-row ${wrong?'has-error':''}"><div><strong>${p.brand}</strong><span>${p.format} × ${p.units}</span><small>${p.sku}</small></div><div class="wh-compare-numbers"><b>${p.need} / ${p.actual}</b><span>${stale?'Не сверено':diff===0?'Совпадает':p.need===0?'Нет в задании':diff>0?'Лишних: '+diff:'Не хватает: '+(-diff)}</span></div>${button('wh-fix','Открыть '+icon('arrow'),p.sku,'wh-inline',`aria-label="Открыть позицию ${p.brand}, ${p.format}"`)}</div>`;}).join('')}${!stale&&issues.some(i=>i.kind!=='count')?`<div class="wh-findings"><h3>Что ещё проверить</h3>${issues.filter(i=>i.kind!=='count').map(i=>button(i.kind==='problem'||i.kind==='damage'?'wh-problem':'wh-open-issue',icon('warning')+e(i.message)+icon('arrow'),i.id,'wh-finding')).join('')}</div>`:''}${game.ready()?`<div class="wh-ready">${icon('check')}<div><strong>Заказ проверен</strong><p>${totalNeed} коробок · ${unitText(unitNeed)}. Замечание по FA-03 зафиксировано, замена проверена.</p></div></div>`:''}</section>`;}
    function terminal(){const c=game.box(selected);if(!c||c.location==='review')return `<aside class="wh-terminal"><header>${icon('scan')}<strong>Терминал стажёра</strong><span></span></header><div class="wh-terminal-empty">${icon('scan')}<h3>Выбери коробку</h3><p>На терминале появятся её этикетка и действия. Сканирование не добавляет товар в заказ.</p></div><footer>Сначала сравни. Затем добавляй.</footer></aside>`;
      const p=getProduct(c.sku),inOrder=c.location==='order';return `<aside class="wh-terminal"><header>${icon('scan')}<strong>Терминал стажёра</strong><span></span></header><div class="wh-terminal-body"><div class="wh-selected-meta"><strong tabindex="-1" id="wh-selected-title">${c.id}</strong><span>${inOrder?'В комплектации':c.address}</span></div><div class="wh-preview ${detail==='scan'?'is-scanning':''}">${carton(c,true)}${detail==='scan'?'<span class="wh-scan-beam"></span>':''}</div><div class="wh-label-data"><strong>${p.brand}</strong><span>${p.format} · ${p.units} ${p.kind==='can'?'банки':'бутылок'}</span><code>${p.sku}</code></div><div class="wh-terminal-reference"><span>По заданию F-78</span><strong>${p.need?boxText(p.need):'Позиции нет в задании'}</strong><span>Собрано: ${boxText(game.rows().find(r=>r.sku===p.sku).actual)}</span></div><div class="wh-scan-result">${c.scanned?icon('check')+' Код считан: '+p.sku:icon('scan')+' Код ещё не считан'}</div>${button('wh-scan',icon('scan')+' Сканировать коробку',c.id,'wh-button wh-button--full')}<div class="wh-inspect"><div><strong>Состояние упаковки</strong><span>${c.inspection==='good'?'Осмотрена · целая':c.inspection==='damage'?'Обнаружено повреждение':'Не осмотрена'}</span></div>${detail==='inspect'?`<p>${c.damaged?'На боковой стенке надрыв, край картона разошёлся.':'Стенки и края коробки целые. Следов повреждения не видно.'}</p><div class="wh-inspect-options">${button('wh-good','Упаковка целая',c.id)}${button('wh-damage','Есть повреждение',c.id)}</div>`:button('wh-inspect',icon('eye')+' Осмотреть упаковку',c.id,'wh-inline')}</div>${inlineMessage?`<p class="wh-context-feedback">${e(inlineMessage)}</p>`:''}${c.inspection==='damage'?button('wh-problem','Сообщить о повреждении',c.id,'primary'):inOrder?button('wh-return','Вернуть на '+c.address,c.id,'wh-button wh-button--full'):button('wh-add','Добавить коробку '+icon('arrow'),c.id,'primary')}<p class="wh-terminal-note">${inOrder?'Возврат уберёт только эту коробку.':'Будет добавлена одна коробка '+c.id+'.'}</p></div></aside>`;
    }
    function problem(){const p=s.problem,c=game.box('FA-03');return `<section class="wh-problem"><div class="wh-section-heading"><h2 tabindex="-1" id="wh-problem-title">Упаковка требует внимания</h2>${button('wh-close-problem','Вернуться к заказу','','wh-inline')}</div><div class="wh-problem-layout"><div class="wh-problem-evidence">${carton(c,true)}<strong>FA-03 · Fancy</strong><span>FA-B05 · ПЭТ 0,5 л × 12</span><p>Надрыв боковой стенки. Этикетка совпадает с заданием.</p></div><div class="wh-problem-action">${!p.reported?`<h3>Как продолжить работу?</h3><p>Товар подходит, но целостность упаковки не подтверждена. Выбери действие в пределах роли стажёра.</p><div class="wh-decisions">${button('wh-report-form','Зафиксировать и сообщить кладовщику', '', 'wh-decision '+(detail==='report'?'is-selected':''))}${button('wh-bad-resolution','Заклеить и отправить','tape','wh-decision')}${button('wh-bad-resolution','Вернуть среди целых и взять другую','return','wh-decision')}</div>${inlineMessage?`<p class="wh-context-feedback">${e(inlineMessage)}</p>`:''}${detail==='report'?`<section class="wh-report-form" aria-label="Сообщение кладовщику"><h3>Сообщение кладовщику</h3><dl><div><dt>Заказ</dt><dd>F-78</dd></div><div><dt>Коробка / адрес</dt><dd>FA-03 / A-02-01</dd></div></dl><fieldset><legend>Что обнаружено?</legend>${[['tear','Надрыв стенки коробки'],['code','Не совпадает код товара'],['units','Не хватает единиц внутри']].map(([value,label])=>`<label><input type="radio" name="wh-reason" data-input="wh-reason" value="${value}" ${reason===value?'checked':''}>${label}</label>`).join('')}</fieldset>${button('wh-send-report','Передать сообщение кладовщику','','primary',reason?'':'disabled')}<small>Учебная запись. Реальное сообщение не отправляется.</small></section>`:''}`:`<div class="wh-report-received">${icon('check')}<strong>Кладовщик получил запись</strong><p>«FA-03 в заказ не включаем. Направь коробку на проверку. Для замены доступна целая Fancy FA-04 в резерве R-01-01».</p></div><div class="wh-problem-log"><span>F-78 · FA-03 · A-02-01</span><strong>Надрыв стенки коробки</strong><span>Ответственный: кладовщик</span></div>${!p.quarantined?button('wh-quarantine',c.location==='order'?'Убрать FA-03 из заказа на проверку':'Отметить FA-03 «На проверку»','','primary'):`<div class="wh-quarantined">${icon('check')} FA-03 направлена на проверку</div>${button('wh-reserve','Найти замену в R-01-01 '+icon('arrow'),'','primary')}`}`}</div></div></section>`;}
    function dispatch(){return `<section class="wh-dispatch"><div class="wh-dispatch-sign">${icon('check')}<span>F-78 · Магазин «Север»</span><strong>${s.transferred?'Передан в зону отгрузки':'Готов к передаче'}</strong></div><div class="wh-loading-scene ${s.transferred?'is-transferred':''}"><div class="wh-loading-door"><span>ЗОНА ОТГРУЗКИ</span><div class="wh-loading-shutter"></div><div class="wh-loading-accepted" ${s.transferred?'':'aria-hidden="true"'}>${s.transferred?icon('check')+' F-78 принят':''}</div></div><div class="wh-loading-cartons">${game.selected().map(c=>carton(c)).join('')}<div class="wh-platform"></div></div><div class="wh-loading-lane"></div></div><div class="wh-dispatch-summary"><div><strong>${totalNeed}</strong><span>коробок</span></div><div><strong>${products.filter(p=>p.need).length}</strong><span>позиции</span></div><div><strong>${unitNeed}</strong><span>единицы продукции</span></div></div>${s.transferred?`<div class="wh-completed"><h2>Заказ передан</h2><p>${e(game.summary())}</p><p>Следующая команда получила точный состав и запись о замене. Погрузку выполняют подготовленные сотрудники.</p>${button('finish','Записать открытие '+icon('arrow'),'','primary')}</div>`:`<p>Все строки совпадают. Коробки просканированы и осмотрены. Повреждённая FA-03 направлена на проверку, замена FA-04 включена в заказ.</p><div class="wh-dispatch-actions">${button('wh-tab','Вернуться к сборке','assembly')}${button('wh-transfer','Передать F-78 в зону отгрузки '+icon('arrow'),'','primary')}</div>`}</section>`;}
    function tray(){return view==='racks'?`<section class="wh-tray" data-drop="assembly" aria-label="Зона добавленных коробок"><header><strong>Зона комплектации · F-78</strong>${button('wh-tab','Открыть состав · '+game.selected().length,'assembly','wh-inline')}</header><div>${game.selected().length?game.selected().map(c=>button('wh-select',carton(c),c.id,'wh-tray-box',`aria-label="Открыть добавленную коробку ${c.id}, ${getProduct(c.sku).brand}, ${getProduct(c.sku).format}"`)).join(''):'<p>Добавленные коробки появятся здесь. Можно перетащить выбранную коробку в эту зону.</p>'}</div></section>`:'';}
    function render(focus=''){
      const active=document.activeElement,oldAction=active?.dataset?.do,oldValue=active?.dataset?.value;
      const html=`<div class="wh-app" data-ui="warehouse"><div class="wh-title-row"><h1>${phase===0?'Склад и отгрузка':phase===3?'Передача заказа':'Собери точный заказ'}</h1><span class="wh-status ${game.ready()||s.transferred?'is-ready':''}">${icon(game.ready()||s.transferred?'check':'box')}${status()}</span></div>${phase===0?intro():phase===3?dispatch():`${guide()}<div class="wh-live-order"><details ${view==='check'?'open':''}><summary>Задание F-78 <span>${game.selected().length} / ${totalNeed} коробок</span></summary>${order(true)}</details><div class="wh-desktop-order">${order(true)}</div></div>${problemOpen?problem():`${tabs()}<div class="wh-workspace"><div class="wh-work-area">${view==='racks'?racks():view==='assembly'?assembly():checkView()}</div>${terminal()}</div><div class="wh-bottom-actions">${button('wh-hint','Как разобраться?','','wh-inline')}${game.ready()?button('wh-to-dispatch','К передаче заказа '+icon('arrow'),'','primary'):button('wh-verify','Сверить заказ '+icon('check'),'','primary')}</div>`}`}</div>`;
      a.draw(html,phases,phase,phase===0?'Прими задание → найди товары → собери и проверь → передай заказ':phase===3?'Передача связывает работу склада и логистики. Готовность подтверждается после сверки.':'Сравнивай задание с фактическим составом. Все ошибки можно исправить.');
      if(phase>0&&phase<3&&!problemOpen)a.content.querySelector('.wh-bottom-actions')?.insertAdjacentHTML('beforebegin',tray());
      const target=focus?a.content.querySelector(focus):oldAction?[...a.content.querySelectorAll('[data-do]:not(:disabled)')].find(n=>n.dataset.do===oldAction&&n.dataset.value===oldValue):null;
      if(target){target.focus({preventScroll:true});if(focus&&window.matchMedia('(max-width:680px)').matches)target.scrollIntoView({block:'nearest',behavior:'instant'});}
      else if(oldAction){const title=a.content.querySelector('.wh-title-row h1');title?.setAttribute('tabindex','-1');title?.focus({preventScroll:true});}
    }
    function openProblem(){const c=game.box('FA-03');if(!s.problem.detected){selected=c.id;address=c.address;view=c.location==='order'?'assembly':'racks';phase=1;detail='inspect';notify('Осмотри оставшуюся Fancy. Код покажет товар, но не состояние упаковки.');render('#wh-selected-title');return;}
      problemOpen=true;phase=2;detail=s.problem.reported?'label':'choice';notify('Зафиксируем наблюдаемый факт и передадим его кладовщику. Решение о допуске стажёр не принимает.');render('#wh-problem-title');}
    function select(id){const c=game.box(id);if(!c||(!game.available(c)&&c.location!=='order'))return;selected=id;detail='label';render('#wh-selected-title');}
    document.body.classList.add('warehouse-active');
    return {
      start:render,done:()=>s.transferred,managesFocus:true,result:()=>({learned:game.summary()}),cleanup(){document.body.classList.remove('warehouse-active');},
      drop(target,id){if(target==='assembly'&&game.add(id)){selected=id;phase=1;view='assembly';notify('Коробка '+id+' добавлена. Проверь её формат и состояние.');render();}},
      input(type,value){if(type==='wh-reason'){reason=value;game.reason(value);const send=a.content.querySelector('[data-do="wh-send-report"]');if(send)send.disabled=false;}},
      act(type,value){
        if(type==='wh-start'){game.start();phase=1;notify('Кладовщик передал F-78. Найди адрес из задания, затем сравни этикетку. Производство передаёт упакованную продукцию, а логистика ждёт точный состав.');render();}
        else if(type==='wh-tab'){view=value;phase=view==='check'?2:1;problemOpen=false;render();}
        else if(type==='wh-address'){address=value;addressScanned=false;selected='';detail='label';render();}
        else if(type==='wh-scan-address'){addressScanned=true;notify('Открыта ячейка '+address+'. Адрес показывает место — теперь сравни маркировку товара.',true);render();}
        else if(type==='wh-select')select(value);
        else if(type==='wh-scan'){if(game.scan(value)){detail='scan';const p=getProduct(game.box(value).sku);notify('Считан '+p.sku+': '+p.brand+', '+p.format+', '+p.units+' единиц. Сравни с заданием. Сканер не выбирает строку за тебя.',false,true);render();}}
        else if(type==='wh-inspect'){detail='inspect';render();}
        else if(type==='wh-good'){const inspected=game.inspect(value,'good');if(inspected){detail='label';notify('Осмотр '+value+' отмечен: упаковка целая.',true,true);}else{detail='inspect';notify('На боковой стенке надрыв, край разошёлся. Подтвердить целостность этой коробки нельзя.',false,true);}render(inspected?'.wh-terminal [data-do="wh-add"], .wh-terminal [data-do="wh-return"]':'');}
        else if(type==='wh-damage'){if(game.inspect(value,'damage'))openProblem();else{notify('На этой упаковке видимого повреждения нет. Осмотри стенки и края ещё раз.',false,true);render();}}
        else if(type==='wh-add'){if(game.add(value)){notify('Добавлена '+value+'. В заказе '+boxText(game.selected().length)+'. Количество сверим по каждой строке.');detail='label';render();}}
        else if(type==='wh-return'){if(game.returnBox(value)){if(selected===value)selected='';notify('Коробка '+value+' возвращена на '+game.box(value).address+'. Остальной состав сохранён.',true);render();}}
        else if(type==='wh-verify'){const issues=game.verify();view='check';phase=2;problemOpen=false;notify(issues.length?'Сверка нашла замечания: '+issues.length+'. Они отмечены у конкретных строк и коробок. Исправь состав и проверь снова.':'Состав, сканирование и осмотр подтверждены. Заказ готов к передаче.',!issues.length);render('#wh-check-title');}
        else if(type==='wh-fix'){address=getProduct(value).address;addressScanned=false;selected='';view='racks';phase=1;notify('Открыта позиция '+getProduct(value).brand+' · '+getProduct(value).format+'. Лишнюю коробку можно вернуть в «Комплектации».');render();}
        else if(type==='wh-open-issue'){selected=value;view='assembly';phase=1;detail='inspect';notify('Проверь коробку '+value+': сканирование кода и осмотр упаковки — отдельные действия.');render('#wh-selected-title');}
        else if(type==='wh-problem')openProblem();
        else if(type==='wh-close-problem'){problemOpen=false;view='assembly';phase=1;render(selected?'#wh-selected-title':'.wh-tab.is-active');}
        else if(type==='wh-report-form'){detail='report';render();}
        else if(type==='wh-bad-resolution'){notify(value==='tape'?'Заклеенный надрыв не подтверждает состояние содержимого. Зафиксируй повреждение и сообщи кладовщику.':'Возвращённая среди целых коробка может снова попасть в сборку. Сначала сообщи, какая именно коробка повреждена.',false,true);render();}
        else if(type==='wh-send-report'){if(game.report()){notify('Учебное сообщение принято кладовщиком. Он открыл резерв для замены. Состав заказа пока не изменился.',true);render();}else{notify('Записываем то, что увидели: код совпадает, коробку не вскрывали. Выбери видимое повреждение стенки.',false,true);render();}}
        else if(type==='wh-quarantine'){game.quarantine();if(selected==='FA-03')selected='';notify('FA-03 направлена на проверку. Теперь сам найди, просканируй и осмотри замену FA-04.',true);render();}
        else if(type==='wh-reserve'){address='R-01-01';addressScanned=false;selected='';problemOpen=false;phase=1;view='racks';detail='label';render();}
        else if(type==='wh-to-dispatch'){if(game.ready()){phase=3;notify('Заказ проверен. Передай его следующей команде.',true);render();}}
        else if(type==='wh-transfer'){if(game.transfer()){notify('F-78 передан в зону отгрузки. Следующая команда получила точный состав и запись о замене.',true);render();}}
        else if(type==='wh-hint'){hint++;notify(hint===1?'Сравни четыре поля: название, код, тара с объёмом, единиц в коробке. Затем количество коробок по каждой строке.':hint===2?'CoolCola в банках и бутылках — разные позиции. Street и Toness отсутствуют в задании. Лишнее можно вернуть.':'У третьей Fancy в A-02-01 повреждена стенка. Осмотри её, зафиксируй надрыв и сообщи кладовщику — он откроет резерв.');render();}
      }
    };
  });
})();

